def _load_balmat_font_base64() -> str:
    """Load BALMAT.otf as base64 for SVG embedding."""
    font_path = Path(__file__).parent.parent.parent / 'assets' / 'fonts' / 'BALMAT.otf'
    if font_path.exists():
        return base64.b64encode(font_path.read_bytes()).decode('ascii')
    return ''

