def generate_svg_styles(footer_height_px: float = REFERENCE_FOOTER_PX) -> str:
    """
    Generate CSS styles for SVG elements with scaled font sizes.

    Font sizes scale proportionally with footer height so that text
    fills the title block appropriately on any paper size.

    Fonts:
    - BALMAT: Used for titles, labels, and headings in the footer
    - Brandon Grotesque: Used for body text and values (loaded via Typekit)

    Args:
        footer_height_px: Footer height in pixels (default 108px = 1.5")

    Returns:
        CSS string with scaled font sizes
    """
    scale = footer_height_px / REFERENCE_FOOTER_PX

    def sz(base: int) -> int:
        """Scale a font size and round to integer."""
        return max(6, round(base * scale))  # Minimum 6px for readability

    # Embed BALMAT font face if available
    font_face = ''
    if _BALMAT_B64:
        font_face = f"""
    @font-face {{
        font-family: 'Balmat';
        src: url('data:font/otf;base64,{_BALMAT_B64}') format('opentype');
        font-weight: normal;
        font-style: normal;
    }}"""

    return f"""
    @import url("https://use.typekit.net/vmk8wft.css");
    {font_face}
    .parcel {{ fill: none; stroke: #2d5a3d; stroke-width: 2; stroke-dasharray: 8,4; }}
    .building {{ fill: #cccccc; stroke: black; stroke-width: 1; opacity: 0.5; }}
    .contour {{ fill: none; stroke: #bdc3c7; stroke-width: 0.5; vector-effect: non-scaling-stroke; }}
    .contour-major {{ fill: none; stroke: #bdc3c7; stroke-width: 1.5; vector-effect: non-scaling-stroke; }}
    .tree {{ fill: #27ae60; fill-opacity: 0.4; stroke: #1e8449; stroke-width: 1; }}
    .soil {{ fill: #d4c4a8; fill-opacity: 0.3; stroke: #a0522d; stroke-width: 0.5; }}
    .soil-well {{ fill: #d4c4a8; fill-opacity: 0.3; stroke: #a0522d; stroke-width: 0.5; }}
    .soil-moderate {{ fill: #c9b896; fill-opacity: 0.3; stroke: #8b7355; stroke-width: 0.5; }}
    .soil-poor {{ fill: #a8c4d4; fill-opacity: 0.4; stroke: #5f9ea0; stroke-width: 0.5; }}
    .soil-verypoor {{ fill: #7bb3c9; fill-opacity: 0.4; stroke: #4682b4; stroke-width: 0.5; }}
    .soil-hydric {{ fill: #6495ed; fill-opacity: 0.5; stroke: #4169e1; stroke-width: 1; }}
    .label {{ font-family: 'brandon-grotesque', 'Brandon Grotesque', Arial, sans-serif; font-size: {sz(10)}px; fill: #2c3e50; text-anchor: middle; paint-order: stroke; }}
    .footer-text {{ font-family: 'brandon-grotesque', 'Brandon Grotesque', Arial, sans-serif; font-size: {sz(10)}px; fill: #333; }}
    .footer-title {{ font-family: 'Balmat', 'Brandon Grotesque', Arial, sans-serif; font-size: {sz(14)}px; font-weight: bold; fill: #000; }}
    .footer-name {{ font-family: 'Balmat', 'Brandon Grotesque', Arial, sans-serif; font-size: {sz(16)}px; font-weight: 700; fill: #000; }}
    .footer-tagline {{ font-family: 'Balmat', 'Brandon Grotesque', Arial, sans-serif; font-size: {sz(9)}px; fill: #333; letter-spacing: 0.5px; }}
    .footer-label {{ font-family: 'Balmat', 'Brandon Grotesque', Arial, sans-serif; font-size: {sz(8)}px; fill: #666; text-transform: uppercase; letter-spacing: 0.5px; }}
    .footer-value {{ font-family: 'brandon-grotesque', 'Brandon Grotesque', Arial, sans-serif; font-size: {sz(10)}px; fill: #000; font-weight: 500; }}
    .footer-status {{ font-family: 'brandon-grotesque', 'Brandon Grotesque', Arial, sans-serif; font-size: {sz(9)}px; fill: #888; font-style: italic; }}
"""

