def geometry_to_path(
    geom,
    to_svg: CoordTransform
) -> str:
    """
    Convert a Shapely geometry to an SVG path string.

    Args:
        geom: Shapely geometry (Point, Polygon, LineString, or Multi* variants)
        to_svg: Coordinate transform function (geo coords -> SVG coords)

    Returns:
        SVG path "d" attribute string
    """
    if isinstance(geom, Point):
        cx, cy = to_svg(geom.x, geom.y)
        # Small circle path for points
        return f"M {cx},{cy} m -5,0 a 5,5 0 1,0 10,0 a 5,5 0 1,0 -10,0"

    elif isinstance(geom, Polygon):
        coords = list(geom.exterior.coords)
    elif isinstance(geom, LineString):
        coords = list(geom.coords)
    elif isinstance(geom, (MultiPolygon, MultiLineString)):
        if len(geom.geoms) > 0:
            return geometry_to_path(geom.geoms[0], to_svg)
        return ""
    else:
        return ""

    if not coords:
        return ""

    path = []
    for i, (x, y) in enumerate(coords):
        sx, sy = to_svg(x, y)
        cmd = "M" if i == 0 else "L"
        path.append(f"{cmd} {sx:.2f},{sy:.2f}")

    if isinstance(geom, Polygon):
        path.append("Z")

    return " ".join(path)

