class LayoutElement:
    """
    An element in the layout with constraint variables.

    Each element has x, y, w, h variables that can be constrained.
    """

    def __init__(self, name: str, solver: SimplexSolver):
        self.name = name
        self.solver = solver

        # Position and size variables
        self.x = Variable(f'{name}_x', 0)
        self.y = Variable(f'{name}_y', 0)
        self.w = Variable(f'{name}_w', 0)
        self.h = Variable(f'{name}_h', 0)

    @property
    def right(self):
        """Right edge expression: x + w"""
        return self.x + self.w

    @property
    def bottom(self):
        """Bottom edge expression: y + h"""
        return self.y + self.h

    @property
    def center_x(self):
        """Horizontal center expression: x + w/2"""
        return self.x + self.w * 0.5

    @property
    def center_y(self):
        """Vertical center expression: y + h/2"""
        return self.y + self.h * 0.5

    def get_rect(self) -> Rect:
        """Get the solved rectangle."""
        return Rect(
            x=self.x.value,
            y=self.y.value,
            w=self.w.value,
            h=self.h.value
        )

    def set_fixed_size(self, width: float, height: float, strength=REQUIRED):
        """Constrain this element to a fixed size."""
        self.solver.add_constraint(self.w == width, strength=strength)
        self.solver.add_constraint(self.h == height, strength=strength)

    def set_min_size(self, min_width: float, min_height: float, strength=REQUIRED):
        """Constrain this element to a minimum size."""
        self.solver.add_constraint(self.w >= min_width, strength=strength)
        self.solver.add_constraint(self.h >= min_height, strength=strength)

